import copy
import unittest

from solution import collect_terminals


class CollectTerminalsTests(unittest.TestCase):
    def sample_tree(self):
        return {
            "name": "root",
            "details": None,
            "children": [
                {
                    "name": "first",
                    "details": {"category": "alpha", "region": "north"},
                    "children": [],
                },
                {
                    "name": "branch",
                    "details": None,
                    "children": [
                        {
                            "name": "second",
                            "details": {"category": "beta", "region": "south"},
                            "children": [],
                        },
                        {
                            "name": "third",
                            "details": {"category": "gamma", "region": "west"},
                            "children": [],
                        },
                    ],
                },
            ],
        }

    def test_depth_first_original_order(self):
        self.assertEqual(
            collect_terminals(self.sample_tree()),
            [
                {"name": "first", "category": "alpha", "region": "north"},
                {"name": "second", "category": "beta", "region": "south"},
                {"name": "third", "category": "gamma", "region": "west"},
            ],
        )

    def test_single_terminal_root(self):
        tree = {
            "name": "only",
            "details": {"category": "leaf", "region": "global"},
            "children": [],
        }
        self.assertEqual(
            collect_terminals(tree),
            [{"name": "only", "category": "leaf", "region": "global"}],
        )

    def test_input_and_results_are_isolated(self):
        tree = self.sample_tree()
        original = copy.deepcopy(tree)
        first = collect_terminals(tree)
        self.assertEqual(tree, original)
        first[0]["name"] = "changed"
        first[1]["category"] = "changed"
        second = collect_terminals(tree)
        self.assertEqual(second[0]["name"], "first")
        self.assertEqual(second[1]["category"], "beta")
        self.assertIsNot(first, second)
        self.assertIsNot(first[0], second[0])

    def test_wrong_types_raise_type_error(self):
        invalid = [
            None,
            [],
            {"name": 1, "details": {"category": "a", "region": "b"}, "children": []},
            {"name": "x", "details": [], "children": []},
            {"name": "x", "details": {"category": 1, "region": "b"}, "children": []},
            {"name": "x", "details": {"category": "a", "region": None}, "children": []},
            {"name": "x", "details": None, "children": {}},
            {"name": "x", "details": None, "children": ["not a node"]},
        ]
        for tree in invalid:
            with self.subTest(tree=tree):
                with self.assertRaises(TypeError):
                    collect_terminals(tree)

    def test_bad_keys_empty_strings_and_structure_raise_value_error(self):
        invalid = [
            {},
            {"name": "x", "details": None, "children": [], "extra": 1},
            {"name": "", "details": {"category": "a", "region": "b"}, "children": []},
            {"name": "x", "details": {"category": "a"}, "children": []},
            {"name": "x", "details": {"category": "a", "region": "b", "extra": "c"}, "children": []},
            {"name": "x", "details": {"category": "", "region": "b"}, "children": []},
            {"name": "x", "details": {"category": "a", "region": ""}, "children": []},
            {"name": "terminal", "details": {"category": "a", "region": "b"}, "children": [
                {"name": "child", "details": {"category": "c", "region": "d"}, "children": []}
            ]},
            {"name": "nonterminal", "details": None, "children": []},
        ]
        for tree in invalid:
            with self.subTest(tree=tree):
                with self.assertRaises(ValueError):
                    collect_terminals(tree)


if __name__ == "__main__":
    unittest.main()

